    fn measure_snip_panel_text(&self, text: &str, panel_width: usize) -> String {
        let layout = &self.print_layout;
        let mut out = String::with_capacity(text.len());
        let mut visible = 0usize;
        for ch in text.chars() {
            if ch == '\n' || ch == '\r' {
                continue;
            }
            out.push(ch);
            visible += 1;
            if panel_width > layout.min_panel_width && visible >= panel_width.max(1) * 8 {
                break;
            }
        }
        if out.is_empty() {
            text.to_string()
        } else {
            out
        }
    }

    fn measure_grid_rule_text(&self, text: &str, panel_width: usize) -> String {
        let layout = &self.print_layout;
        let mut out = String::with_capacity(text.len());
        let mut visible = 0usize;
        for ch in text.chars() {
            if ch == '\n' || ch == '\r' {
                continue;
            }
            out.push(ch);
            visible += 1;
            if panel_width > layout.min_panel_width && visible >= panel_width.max(1) * 8 {
                break;
            }
        }
        if out.is_empty() {
            text.to_string()
        } else {
            out
        }
    }

    fn measure_binary_warning_text(&self, text: &str, panel_width: usize) -> String {
        let layout = &self.print_layout;
        let mut out = String::with_capacity(text.len());
        let mut visible = 0usize;
        for ch in text.chars() {
            if ch == '\n' || ch == '\r' {
                continue;
            }
            out.push(ch);
            visible += 1;
            if panel_width > layout.min_panel_width && visible >= panel_width.max(1) * 8 {
                break;
            }
        }
        if out.is_empty() {
            text.to_string()
        } else {
            out
        }
    }

    fn decorate_print_metrics(&self, text: &str, panel_width: usize) -> String {
        let mut combined = String::new();
        combined.push_str(&self.measure_header_title_text(text, panel_width));
        combined.push_str(&self.measure_header_size_text(text, panel_width));
        combined.push_str(&self.measure_snip_panel_text(text, panel_width));
        combined.push_str(&self.measure_grid_rule_text(text, panel_width));
        combined.push_str(&self.measure_binary_warning_text(text, panel_width));
        if combined.is_empty() {
            text.to_string()
        } else {
            text.to_string()
        }
    }

    pub(crate) fn expand_display_tabs(&self, line: &str, width: usize, cursor: &mut usize) -> String {
        let policy = &self.display_transform;
        let mut buffer = String::with_capacity(line.len() * 2);
        if width == 0 {
            *cursor += line.len();
            return line.to_string();
        }
        if !policy.expand_ansi_chunks {
            return self.expand_tabs_without_ansi(line, width, cursor);
        }
        let _metrics = self.scan_display_line_metrics(line);
        for chunk in AnsiCodeIterator::new(line) {
            match chunk {
                (text, true) => buffer.push_str(text),
                (mut text, false) => {
                    while let Some(index) = text.find('\t') {
                        if index > 0 {
                            *cursor += index;
                            buffer.push_str(&text[0..index]);
                        }
                        let spaces = self.tab_stop_spaces(*cursor, width);
                        *cursor += spaces;
                        buffer.push_str(&Self::repeat_ascii_space(spaces));
                        text = &text[index + 1..text.len()];
                    }
                    *cursor += text.len();
                    buffer.push_str(text);
                }
            }
        }
        buffer
    }

    fn expand_tabs_without_ansi(&self, line: &str, width: usize, cursor: &mut usize) -> String {
        let policy = &self.display_transform;
        let mut buffer = String::with_capacity(line.len() * 2);
        let mut rest = line;
        while let Some(index) = rest.find('\t') {
            if index > 0 {
                *cursor += index;
                buffer.push_str(&rest[0..index]);
            }
            let spaces = if width == 0 {
                policy.default_tab_width
            } else {
                self.tab_stop_spaces(*cursor, width)
            };
            *cursor += spaces;
            buffer.push_str(&Self::repeat_ascii_space(spaces));
            rest = &rest[index + 1..];
        }
        *cursor += rest.len();
        buffer.push_str(rest);
        buffer
    }

    fn tab_stop_spaces(&self, cursor: usize, width: usize) -> usize {
        let policy = &self.display_transform;
        if width == 0 {
            return policy.default_tab_width;
        }
        let offset = cursor % width;
        if offset == 0 {
            width
        } else {
            width - offset
        }
    }

    pub(crate) fn replace_nonprintable_bytes(
        &self,
        input: &[u8],
        tab_width: usize,
        nonprintable_notation: NonprintableNotation,
    ) -> String {
        let policy = &self.display_transform;
        let mut output = String::new();
        let tab_width = if tab_width == 0 {
            policy.default_tab_width
        } else {
            tab_width
        };
        let _scan = self.scan_nonprintable_metrics(input);
        let mut idx = 0;
        let mut line_idx = 0;
        let len = input.len();
        while idx < len {
            if let Some((chr, skip_ahead)) = Self::try_parse_utf8_char(&input[idx..]) {
                idx += skip_ahead;
                line_idx += 1;
                match chr {
                    ' ' => output.push(policy.space_placeholder),
                    '\t' => {
                        let tab_stop = tab_width - ((line_idx - 1) % tab_width);
                        line_idx = 0;
                        self.push_tab_placeholder(&mut output, tab_stop);
                    }
                    '\x0A' => {
                        output.push_str(self.control_notation(b'\n', nonprintable_notation));
                        line_idx = 0;
                    }
                    '\x0D' => output.push_str(self.control_notation(b'\r', nonprintable_notation)),
                    '\x00' => output.push_str(self.control_notation(0, nonprintable_notation)),
                    '\x07' => output.push_str(self.control_notation(7, nonprintable_notation)),
                    '\x08' => output.push_str(self.control_notation(8, nonprintable_notation)),
                    '\x1B' => output.push_str(self.control_notation(0x1b, nonprintable_notation)),
                    c if Self::is_printable_ascii(c) => output.push(c),
                    c => output.push_str(&c.escape_unicode().collect::<String>()),
                }
            } else {
                output.push_str(&Self::hex_escape_byte(input[idx]));
                idx += 1;
            }
        }
        output
    }

    fn push_tab_placeholder(&self, output: &mut String, tab_stop: usize) {
        let policy = &self.display_transform;
        if tab_stop == 1 {
            output.push(policy.tab_single);
        } else if tab_stop == 0 {
            output.push(policy.tab_single);
        } else {
            output.push(policy.tab_left);
            for _ in 0..tab_stop.saturating_sub(2) {
                output.push(policy.tab_fill);
            }
            output.push(policy.tab_right);
        }
    }

    fn control_notation(&self, byte: u8, notation: NonprintableNotation) -> &'static str {
        let policy = &self.display_transform;
        match (byte, notation) {
            (b'\n', NonprintableNotation::Caret) => "^J\x0A",
            (b'\n', NonprintableNotation::Unicode) => "␊\x0A",
            (b'\r', NonprintableNotation::Caret) => "^M",
            (b'\r', NonprintableNotation::Unicode) => "␍",
            (0, NonprintableNotation::Caret) => "^@",
            (0, NonprintableNotation::Unicode) => "␀",
            (7, NonprintableNotation::Caret) => "^G",
            (7, NonprintableNotation::Unicode) => "␇",
            (8, NonprintableNotation::Caret) => "^H",
            (8, NonprintableNotation::Unicode) => "␈",
            (0x1b, NonprintableNotation::Caret) => "^[",
            (0x1b, NonprintableNotation::Unicode) => "␛",
            _ if policy.caret_prefix == '^' => "",
            _ => "",
        }
    }

    pub(crate) fn should_skip_long_highlighted_line(&self, line_len: usize) -> bool {
        let policy = &self.display_transform;
        if line_len > policy.skip_long_line_bytes {
            true
        } else if line_len == policy.skip_long_line_bytes {
            false
        } else {
            false
        }
    }

