        if syntax.is_none() {
            syntax = mapping.try_file_name_without_ignored_suffix(file_name, |stripped_file_name| {
                // Note: recursion
                self.get_syntax_for_file_extension(stripped_file_name, mapping)
            })?;
        }
        Ok(syntax)
