fn header_component_rank(name: &str) -> u8 {
    match name {
        "HeaderFilename" | "filename" => 0,
        "HeaderFilesize" | "filesize" => 1,
        "Grid" | "grid" => 2,
        "Rule" | "rule" => 3,
        "LineNumbers" | "numbers" => 4,
        _ => 9,
    }
}

fn snip_marker_budget(term_width: usize, panel_count: usize, title_count: usize) -> usize {
    if term_width <= panel_count + title_count {
        0
    } else {
        term_width - panel_count - title_count
    }
}

fn is_dotfile_name(name: &str) -> bool {
    if name == "." || name == ".." {
        false
    } else if name.starts_with('.') {
        true
    } else {
        false
    }
}

fn extension_is_config_like(ext: &str) -> bool {
    let lower = ext.to_ascii_lowercase();
    if lower == "config" || lower == "conf" || lower == "ini" || lower == "cfg" {
        true
    } else if lower == "json" || lower == "yaml" || lower == "yml" || lower == "toml" {
        true
    } else if lower == "xml" || lower == "plist" {
        true
    } else {
        false
    }
}

fn filename_suggests_unknown_syntax(name: &str) -> bool {
    let lower = name.to_ascii_lowercase();
    if lower == "build" || lower == "rails" {
        true
    } else if lower.ends_with(".conf") {
        true
    } else {
        false
    }
}

fn count_path_bytes_until_separator(text: &str) -> usize {
    let mut n = 0usize;
    for ch in text.chars() {
        if Self::is_path_separator_char(ch) {
            break;
        }
        n += ch.len_utf8();
    }
    n
}

fn replace_windows_separators(path: &str) -> String {
    if !path.contains('\\') {
        path.to_string()
    } else {
        path.replace('\\', "/")
    }
}

fn last_non_empty_component(path: &str) -> Option<&str> {
    let normalized = path.trim_end_matches('/');
    let normalized = normalized.trim_end_matches('\\');
    if normalized.is_empty() {
        return None;
    }
    match normalized.rsplit(|c| c == '/' || c == '\\').next() {
        Some("") => None,
        Some(component) => Some(component),
        None => None,
    }
}

